import Intl from '@baifendian/adhere-util-intl';
function buildPathBrowseAndUpload(requestPathInsert, title) {
  return function (insertFn) {
    requestPathInsert({
      title: title,
      onInsert: function (path) {
        insertFn(path, path, path);
      }
    });
  };
}
/** 媒体插入固定为路径方式 */
export function buildRichEditorMenuConf(options) {
  var requestPathInsert = options.requestPathInsert;
  return {
    uploadImage: {
      customBrowseAndUpload: buildPathBrowseAndUpload(requestPathInsert, Intl.get('rich_editor_image'))
    },
    uploadVideo: {
      customBrowseAndUpload: buildPathBrowseAndUpload(requestPathInsert, Intl.get('rich_editor_video'))
    },
    insertLink: {
      checkLink: function () {
        return true;
      },
      parseLinkUrl: function (url) {
        return url;
      },
      customBrowseAndUpload: function (insertFn) {
        requestPathInsert({
          title: Intl.get('rich_editor_file'),
          onInsert: function (path) {
            return insertFn(path, path);
          }
        });
      }
    }
  };
}